using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "DrifterCatcherOmenData", menuName = "Data/Battle/Omens System/Omen Data/Austra/DrifterCatcherOmenData")]
public class DrifterCatcherOmenData : OnStartOfBattleOmenData
{
	[Header("Convert Omen")]
	[SerializeField]
	private OmenLogic omenLogicForDescription;

	[SerializeField]
	private int purificationAmount = 45;

	private Action<GameObject> onDodgeOmenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		onDodgeOmenAction = delegate(GameObject unitThatDodged)
		{
			CorruptedAnimalCorruptionStats component = unitThatDodged.GetComponent<CorruptedAnimalCorruptionStats>();
			if (component != null)
			{
				component.Purify(purificationAmount, null);
				omenInstance.EnqueueOmenFeedbackAndPlay();
			}
		};
		ReferenceSingleton<AustraOmensHandler>.Instance.OnDodgeOmenActions.Add(onDodgeOmenAction);
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<AustraOmensHandler>.Instance.OnDodgeOmenActions.Remove(onDodgeOmenAction);
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(GetOmenRawLocalizedDescription(), omenLogicForDescription.GetLocalizedOmenLogicDescription(null, purificationAmount) + "\n" + base.OmenConvertedDescription());
	}
}
